import javax.net.ssl.HostnameVerifier;

public class AllowAllHostnameVerifierDetector extends Detector implements SourceCodeScanner {
    public static final Issue ISSUE = Issue.create(
        "AllowAllHostnameVerifier",
        "Insecure `HostnameVerifier`",
        "This `HostnameVerifier` implementation unconditionally returns true for any hostname. "
            + "Accepting all hostnames allows an attacker to perform a man-in-the-middle attack "
            + "against your app. You should use the default hostname verifier instead.",
        Category.SECURITY,
        6,
        Severity.WARNING,
        new Implementation(
            AllowAllHostnameVerifierDetector.class,
            Scope.JAVA_FILE_SCOPE
        )
    );

    private static final String HOSTNAME_VERIFIER = "javax.net.ssl.HostnameVerifier";

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Arrays.asList(UClass.class, ULambdaExpression.class, UCallExpression.class);
    }

    @Override
    public UElementHandler createUastHandler(JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (!context.getEvaluator().implementsInterface(node, HOSTNAME_VERIFIER, false)) {
                    return;
                }
                for (UMethod method : node.getMethods()) {
                    if (isVerifyMethod(method) && alwaysReturnsTrue(method)) {
                        UElement locationNode = node.isAnonymous() ? node : method;
                        context.report(ISSUE, locationNode, context.getLocation(locationNode),
                            "Using a `HostnameVerifier` that unconditionally returns true is insecure");
                        break;
                    }
                }
            }

            @Override
            public void visitLambdaExpression(@NotNull ULambdaExpression node) {
                if (!isHostnameVerifierLambda(context, node)) {
                    return;
                }
                if (lambdaAlwaysReturnsTrue(node)) {
                    context.report(ISSUE, node, context.getLocation(node),
                        "Using a `HostnameVerifier` that unconditionally returns true is insecure");
                }
            }

            @Override
            public void visitCallExpression(@NotNull UCallExpression node) {
                // Flag construction of the well-known insecure Apache class.
                if (node.getKind() == UastCallKind.CONSTRUCTOR_CALL) {
                    PsiMethod constructor = node.resolve();
                    if (constructor != null) {
                        String className = constructor.getContainingClass().getQualifiedName();
                        if ("org.apache.http.conn.ssl.AllowAllHostnameVerifier".equals(className)) {
                            context.report(ISSUE, node, context.getLocation(node),
                                "Using `AllowAllHostnameVerifier` is insecure");
                        }
                    }
                }
            }
        };
    }

    private static boolean isVerifyMethod(UMethod method) {
        if (!"verify".equals(method.getName())) return false;
        if (method.getParameterList().getParametersCount() != 2) return false;
        // Return type boolean
        PsiType returnType = method.getReturnType();
        return returnType != null && returnType.equalsToText("boolean");
    }

    private static boolean alwaysReturnsTrue(UMethod method) {
        UExpression body = method.getUastBody();
        if (body == null) return false;
        List<UReturnExpression> returns = new ArrayList<>();
        collectReturns(body, returns);
        if (returns.isEmpty()) return false;
        for (UReturnExpression ret : returns) {
            UExpression expr = ret.getReturnExpression();
            if (expr == null) return false;
            if (!isTrue(expr)) return false;
        }
        return true;
    }

    private static void collectReturns(UElement element, List<UReturnExpression> out) {
        if (element instanceof UReturnExpression) {
            out.add((UReturnExpression) element);
            return;
        }
        if (element instanceof ULiteralExpression
                || element instanceof UReferenceExpression) {
            return;
        }
        for (UElement child : element.getChildren()) {
            if (child instanceof UExpression || child instanceof UReturnExpression || child instanceof UBlockExpression) {
                collectReturns(child, out);
            }
        }
    }

    private static boolean isTrue(UExpression expr) {
        Object value = UastLiteralUtils.getValueIfLiteral(expr); // not sure class exists
        return expr instanceof ULiteralExpression
            && ((ULiteralExpression) expr).isBoolean()
            && Boolean.TRUE.equals(((ULiteralExpression) expr).getValue());
    }

    private static boolean isHostnameVerifierLambda(JavaContext context, ULambdaExpression lambda) {
        // Get functional interface type
        PsiType type = lambda.getFunctionalInterfaceType();
        if (type == null) return false;
        PsiClass psiClass = PsiUtil.resolveClassInClassTypeOnly(type); // need import
        if (psiClass == null) return false;
        return context.getEvaluator().implementsInterface(psiClass, HOSTNAME_VERIFIER, false);
    }

    private static boolean lambdaAlwaysReturnsTrue(ULambdaExpression lambda) {
        UExpression body = lambda.getBody();
        if (body == null) return false;
        // Single expression lambda: e.g. `(a,b) -> true`
        if (body instanceof ULiteralExpression) {
            return isTrue(body);
        }
        // Block lambda: collect returns.
        List<UReturnExpression> returns = new ArrayList<>();
        collectReturns(body, returns);
        if (returns.isEmpty()) return false;
        for (UReturnExpression ret : returns) {
            UExpression expr = ret.getReturnExpression();
            if (expr == null || !isTrue(expr)) return false;
        }
        return true;
    }
}

